{% if product.available %}
  <p>{{ product.title | upcase }}</p>
  <p>{{ product.price | money }} incl. taxes</p>
{% else %}
  <p>Sold out - <a href="#notify">notify me</a></p>
{% endif %}

{{ product.title }}
{{ product.price | money }}
{{ 'now' | date: '%B %d, %Y' }}
{{ product.description | strip_html | truncate: 160 }}

{% if product.available %}
  In stock
{% elsif product.tags contains 'preorder' %}
  Pre-order
{% else %}
  Sold out
{% endif %}

{% for variant in product.variants %}
  <option value="{{ variant.id }}">{{ variant.title }} - {{ variant.price | money }}</option>
{% endfor %}

{% assign specs = product.metafields.custom.specs.value %}
{% if specs %}
  <table class="specs">
    {% for spec in specs %}
      <tr><th>{{ spec.key }}</th><td>{{ spec.value }}</td></tr>
    {% endfor %}
  </table>
{% endif %}

{%- assign variant = product.selected_or_first_available_variant -%}
<p class="price">
  <span class="price__current">{{ variant.price | money }}</span>
  {%- if variant.compare_at_price > variant.price -%}
    <s class="price__compare">{{ variant.compare_at_price | money }}</s>
    <span class="price__save">Save {{ variant.compare_at_price | minus: variant.price | money }}</span>
  {%- endif -%}
</p>

{%- assign v = product.selected_or_first_available_variant -%}
{%- if v.inventory_management == 'shopify' and v.inventory_quantity <= 5 and v.inventory_quantity > 0 -%}
  <p class="stock stock--low">Only {{ v.inventory_quantity }} left in stock</p>
{%- elsif v.available -%}
  <p class="stock stock--ok">In stock</p>
{%- else -%}
  <p class="stock stock--out">Sold out</p>
{%- endif -%}

