          "id": "image",
          "label": "Card Image"
        },
        {
          "type": "inline_richtext",
          "id": "title",
          "label": "Card Title",
          "default": "Feature Title"
        },
        {
          "type": "richtext",
          "id": "description",
          "label": "Card Description"
        }
      ]
